from django.conf import settings
from django.db import models


class NotificationQuerySet(models.QuerySet):
    def unread(self) -> "NotificationQuerySet":
        return self.filter(is_read=False)


NotificationManager = models.Manager.from_queryset(NotificationQuerySet)


class Notification(models.Model):
    class Verb(models.TextChoices):
        FOLLOW = "follow", "followed you"
        FAVORITE = "favorite", "favorited your article"
        COMMENT = "comment", "commented on your article"

    recipient = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="notifications"
    )
    actor = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="+")
    verb = models.CharField(max_length=20, choices=Verb.choices)
    article = models.ForeignKey("articles.Article", on_delete=models.CASCADE, null=True, blank=True)

    is_read = models.BooleanField(default=False, db_index=True)
    created = models.DateTimeField(auto_now_add=True, db_index=True)

    objects = NotificationManager()

    class Meta:
        ordering = ["-created"]

    def __str__(self) -> str:
        return f"{self.actor} {self.get_verb_display()} → {self.recipient}"

